#include "doveos.h"
#include <gdk/gdkkeysyms.h>
#include <string.h>
enum {CLOSED,OPEN,FLAG,QUESTION,CELL=24};
typedef struct {guint8 mine,state,adjacent;} Cell;
static Cell cells[480];static int columns=8,rows=8,mines=10,flags,opened,elapsed,hit=-1,selected,level;
static gboolean planted,ended,won,marks=TRUE,testing;static GRand *randomness;static guint timer;
static GtkWidget *window,*board,*face,*remaining,*clock_label;static DovePreferences *prefs;
static void refresh(void){if(board)gtk_widget_queue_draw(board);if(face)gtk_widget_queue_draw(face);char text[12];if(remaining){g_snprintf(text,sizeof text,"%03d",mines-flags);gtk_label_set_text(GTK_LABEL(remaining),text);}if(clock_label){g_snprintf(text,sizeof text,"%03d",MIN(999,elapsed));gtk_label_set_text(GTK_LABEL(clock_label),text);}}
static void stop_timer(void){if(timer){g_source_remove(timer);timer=0;}}
static void new_game(void){stop_timer();memset(cells,0,sizeof cells);flags=opened=elapsed=selected=0;hit=-1;planted=ended=won=FALSE;if(board)gtk_widget_set_size_request(board,columns*CELL,rows*CELL);refresh();if(window)gtk_window_resize(GTK_WINDOW(window),columns*CELL+22,rows*CELL+107);}
static gboolean tick(gpointer data){(void)data;if(ended){timer=0;return FALSE;}elapsed++;refresh();return TRUE;}
static gboolean near(int a,int b){return abs(a%columns-b%columns)<=1&&abs(a/columns-b/columns)<=1;}
static void plant(int first){int count=0;while(count<mines){int n=g_rand_int_range(randomness,0,columns*rows);if(!cells[n].mine&&!near(n,first)){cells[n].mine=TRUE;count++;}}for(int n=0;n<columns*rows;n++)for(int k=0;k<columns*rows;k++)if(cells[k].mine&&near(n,k)&&n!=k)cells[n].adjacent++;planted=TRUE;if(!testing)timer=dove_timer(1000,tick,NULL);}
static void reveal(int n){
 if(ended||n<0||n>=columns*rows||cells[n].state==OPEN||cells[n].state==FLAG)return;
 if(!planted)plant(n);
 if(cells[n].mine){hit=n;ended=TRUE;stop_timer();refresh();return;}
 int queue[480],head=0,tail=0;cells[n].state=OPEN;opened++;queue[tail++]=n;
 while(head<tail){int current=queue[head++];if(cells[current].adjacent)continue;int x=current%columns,y=current/columns;
  for(int yy=MAX(0,y-1);yy<=MIN(rows-1,y+1);yy++)for(int xx=MAX(0,x-1);xx<=MIN(columns-1,x+1);xx++){int k=yy*columns+xx;if(cells[k].state!=OPEN&&cells[k].state!=FLAG&&!cells[k].mine){cells[k].state=OPEN;opened++;queue[tail++]=k;}}
 }
 if(opened==columns*rows-mines){ended=won=TRUE;stop_timer();for(int k=0;k<columns*rows;k++)if(cells[k].mine)cells[k].state=FLAG;flags=mines;
  if(prefs&&!testing){char key[16];g_snprintf(key,sizeof key,"level-%d",level);int best=dove_preferences_int(prefs,"Best",key,999,0,999);if(elapsed<best){g_key_file_set_integer(prefs->values,"Best",key,elapsed);GError *error=NULL;if(!dove_preferences_save(prefs,&error)){g_warning("Best time not saved: %s",error->message);g_error_free(error);}}}
 }refresh();
}
static void flag(int n){if(ended||cells[n].state==OPEN)return;if(cells[n].state==CLOSED){cells[n].state=FLAG;flags++;}else if(cells[n].state==FLAG){cells[n].state=marks?QUESTION:CLOSED;flags--;}else cells[n].state=CLOSED;refresh();}
static void chord(int n){if(ended||cells[n].state!=OPEN||!cells[n].adjacent)return;int count=0;for(int k=0;k<columns*rows;k++)if(k!=n&&near(k,n)&&cells[k].state==FLAG)count++;if(count==cells[n].adjacent)for(int k=0;k<columns*rows&&!ended;k++)if(k!=n&&near(k,n))reveal(k);}
static void color(cairo_t *cr,double r,double g,double b){cairo_set_source_rgb(cr,r,g,b);}
static void line(cairo_t *cr,int x,int y,int a,int b){cairo_move_to(cr,x+.5,y+.5);cairo_line_to(cr,a+.5,b+.5);cairo_stroke(cr);}
static void bomb(cairo_t *cr,int x,int y){color(cr,0,0,0);cairo_arc(cr,x+12,y+12,6,0,6.2832);cairo_fill(cr);for(int k=-1;k<=1;k++){line(cr,x+12+k*8,y+4,x+12-k*8,y+20);line(cr,x+4,y+12+k*8,x+20,y+12-k*8);}color(cr,1,1,1);cairo_rectangle(cr,x+9,y+9,2,2);cairo_fill(cr);}
static gboolean draw_board(GtkWidget *widget,GdkEventExpose *event,gpointer data){(void)event;(void)data;cairo_t *cr=gdk_cairo_create(gtk_widget_get_window(widget));cairo_set_antialias(cr,CAIRO_ANTIALIAS_NONE);cairo_set_line_width(cr,1);
 const double colors[8][3]={{0,0,1},{0,.5,0},{1,0,0},{0,0,.5},{.5,0,0},{0,.5,.5},{0,0,0},{.5,.5,.5}};
 for(int n=0;n<columns*rows;n++){int x=n%columns*CELL,y=n/columns*CELL;Cell c=cells[n];color(cr,.75,.75,.75);cairo_rectangle(cr,x,y,CELL,CELL);cairo_fill(cr);
  gboolean flat=c.state==OPEN||(ended&&!won&&c.mine&&c.state!=FLAG);if(flat){color(cr,.5,.5,.5);line(cr,x,y,x+CELL-1,y);line(cr,x,y,x,y+CELL-1);}else{color(cr,1,1,1);line(cr,x,y,x+23,y);line(cr,x,y,x,y+23);line(cr,x+1,y+1,x+22,y+1);line(cr,x+1,y+1,x+1,y+22);color(cr,.5,.5,.5);line(cr,x+23,y,x+23,y+23);line(cr,x,y+23,x+23,y+23);line(cr,x+22,y+1,x+22,y+22);line(cr,x+1,y+22,x+22,y+22);}
  if(ended&&!won&&c.mine&&c.state!=FLAG){if(n==hit){color(cr,1,0,0);cairo_rectangle(cr,x+1,y+1,22,22);cairo_fill(cr);}bomb(cr,x,y);}
  else if(c.state==FLAG){color(cr,0,0,0);cairo_rectangle(cr,x+11,y+6,2,13);cairo_rectangle(cr,x+6,y+18,12,3);cairo_fill(cr);color(cr,1,0,0);cairo_move_to(cr,x+11,y+5);cairo_line_to(cr,x+5,y+10);cairo_line_to(cr,x+11,y+13);cairo_close_path(cr);cairo_fill(cr);if(ended&&!won&&!c.mine){color(cr,1,0,0);line(cr,x+4,y+4,x+20,y+20);line(cr,x+20,y+4,x+4,y+20);}}
  else if(c.state==QUESTION||(c.state==OPEN&&c.adjacent)){char text[2]={c.state==QUESTION?'?':'0'+c.adjacent,0};if(c.state==QUESTION)color(cr,0,0,0);else color(cr,colors[c.adjacent-1][0],colors[c.adjacent-1][1],colors[c.adjacent-1][2]);cairo_select_font_face(cr,"Sans",CAIRO_FONT_SLANT_NORMAL,CAIRO_FONT_WEIGHT_BOLD);cairo_set_font_size(cr,17);cairo_move_to(cr,x+7,y+18);cairo_show_text(cr,text);}
  if(n==selected&&GTK_WIDGET_HAS_FOCUS(widget)){color(cr,0,0,0);double dash[]={1,1};cairo_set_dash(cr,dash,2,0);cairo_rectangle(cr,x+3.5,y+3.5,17,17);cairo_stroke(cr);cairo_set_dash(cr,NULL,0,0);}
 }cairo_destroy(cr);return TRUE;}
static gboolean draw_face(GtkWidget *widget,GdkEventExpose *event,gpointer data){(void)event;(void)data;cairo_t *cr=gdk_cairo_create(gtk_widget_get_window(widget));cairo_set_line_width(cr,1);color(cr,1,1,0);cairo_arc(cr,12,12,10,0,6.2832);cairo_fill_preserve(cr);color(cr,0,0,0);cairo_stroke(cr);if(ended&&!won){line(cr,7,7,10,10);line(cr,10,7,7,10);line(cr,15,7,18,10);line(cr,18,7,15,10);cairo_arc(cr,12,20,5,3.6,5.8);cairo_stroke(cr);}else{cairo_rectangle(cr,7,8,2,2);cairo_rectangle(cr,15,8,2,2);cairo_fill(cr);cairo_arc(cr,12,11,6,.3,2.84);cairo_stroke(cr);}cairo_destroy(cr);return TRUE;}
static gboolean press(GtkWidget *widget,GdkEventButton *event,gpointer data){(void)data;int x=event->x/CELL,y=event->y/CELL;if(x<0||y<0||x>=columns||y>=rows)return FALSE;selected=y*columns+x;gtk_widget_grab_focus(widget);if(event->button==3)flag(selected);else if(event->button==2||(event->button==1&&event->type==GDK_2BUTTON_PRESS))chord(selected);else if(event->button==1)reveal(selected);refresh();return TRUE;}
static void reset_click(GtkWidget *widget,gpointer data){(void)widget;(void)data;new_game();}
static gboolean key(GtkWidget *widget,GdkEventKey *event,gpointer data){(void)widget;(void)data;int x=selected%columns,y=selected/columns;switch(event->keyval){case GDK_Left:x=MAX(0,x-1);break;case GDK_Right:x=MIN(columns-1,x+1);break;case GDK_Up:y=MAX(0,y-1);break;case GDK_Down:y=MIN(rows-1,y+1);break;case GDK_space:reveal(selected);break;case GDK_f:case GDK_F:flag(selected);break;case GDK_Return:case GDK_KP_Enter:chord(selected);break;case GDK_F2:new_game();break;default:return FALSE;}selected=y*columns+x;refresh();return TRUE;}
static void difficulty(GtkCheckMenuItem *item,gpointer data){if(!gtk_check_menu_item_get_active(item))return;level=GPOINTER_TO_INT(data);columns=level==0?8:level==1?16:30;rows=level==0?8:16;mines=level==0?10:level==1?40:99;new_game();}
static void mark_toggle(GtkCheckMenuItem *item,gpointer data){(void)data;marks=gtk_check_menu_item_get_active(item);if(!marks)for(int n=0;n<columns*rows;n++)if(cells[n].state==QUESTION)cells[n].state=CLOSED;refresh();}
static void about(GtkWidget *widget,gpointer data){(void)widget;(void)data;dove_message(GTK_WINDOW(window),"DoveOS Minesweeper\nDoveOS\n\nLeft click: reveal. Right click: flag / question mark.\nDouble click or middle click: open around a number.\nArrows: select. Space: reveal. F: flag. Enter: open around. F2: new game.\nThe first click and its neighbours are safe.");}
static void best(GtkWidget *widget,gpointer data){(void)widget;(void)data;char text[160];int times[3];for(int i=0;i<3;i++){char name[16];g_snprintf(name,sizeof name,"level-%d",i);times[i]=prefs?dove_preferences_int(prefs,"Best",name,999,0,999):999;}g_snprintf(text,sizeof text,"Best times\n\nBeginner: %d seconds\nIntermediate: %d seconds\nExpert: %d seconds\n\n999 = no completed game yet.",times[0],times[1],times[2]);dove_message(GTK_WINDOW(window),text);}
static void quit(GtkWidget *widget,gpointer data){(void)widget;(void)data;stop_timer();gtk_main_quit();}
static void exit_click(GtkWidget *widget,gpointer data){(void)widget;(void)data;gtk_widget_destroy(window);}
static GtkWidget *menu_item(GtkWidget *menu,const char *name,GCallback callback){GtkWidget *item=dove_menuitem(name);gtk_menu_shell_append(GTK_MENU_SHELL(menu),item);if(callback)g_signal_connect(item,"activate",callback,NULL);return item;}
static GtkWidget *counter(void){GtkWidget *frame=gtk_frame_new(NULL);gtk_frame_set_shadow_type(GTK_FRAME(frame),GTK_SHADOW_IN);GtkWidget *label=dove_label("000");gtk_misc_set_alignment(GTK_MISC(label),.5,.5);GdkColor fg,bg;gdk_color_parse("#ff0000",&fg);gdk_color_parse("#000000",&bg);GtkWidget *event=gtk_event_box_new();gtk_widget_modify_bg(event,GTK_STATE_NORMAL,&bg);gtk_widget_modify_fg(label,GTK_STATE_NORMAL,&fg);PangoFontDescription *font=pango_font_description_from_string("Monospace Bold 17");gtk_widget_modify_font(label,font);pango_font_description_free(font);gtk_container_add(GTK_CONTAINER(event),label);gtk_container_add(GTK_CONTAINER(frame),event);g_object_set_data(G_OBJECT(frame),"label",label);return frame;}
static int self_test(void){testing=TRUE;int failures=0;for(int l=0;l<3;l++){level=l;columns=l==0?8:l==1?16:30;rows=l==0?8:16;mines=l==0?10:l==1?40:99;new_game();flag(0);reveal(0);if(planted)failures++;flag(0);flag(0);reveal(0);int count=0;for(int n=0;n<columns*rows;n++){count+=cells[n].mine;if(near(n,0)&&cells[n].mine)failures++;}if(count!=mines||cells[0].state!=OPEN)failures++;for(int n=0;n<columns*rows;n++)if(!cells[n].mine)reveal(n);if(!won||!ended||opened!=columns*rows-mines||flags!=mines)failures++;new_game();reveal(0);for(int n=0;n<columns*rows;n++)if(cells[n].mine){reveal(n);break;}if(!ended||won||hit<0)failures++;}g_print("MINESWEEPER_CHECK failures=%d\n",failures);return failures?1:0;}
int main(int argc,char **argv){randomness=g_rand_new();if(argc>1&&!strcmp(argv[1],"--self-test")){int result=self_test();g_rand_free(randomness);return result;}gtk_init(&argc,&argv);prefs=dove_preferences_open("minesweeper",NULL,NULL);window=dove_form("Minesweeper",216,300);gtk_window_set_resizable(GTK_WINDOW(window),FALSE);gtk_window_set_wmclass(GTK_WINDOW(window),"DoveMinesweeper","DoveMinesweeper");gtk_window_set_icon_from_file(GTK_WINDOW(window),"/media/usb0/DoveOS-v2/ClassicApps/icons/mines-48.png",NULL);g_signal_connect(window,"destroy",G_CALLBACK(quit),NULL);
 GtkWidget *box=dove_layout(FALSE);gtk_container_set_border_width(GTK_CONTAINER(box),6);gtk_container_add(GTK_CONTAINER(window),box);GtkWidget *bar=dove_menubar();dove_pack(box,bar,FALSE);GtkWidget *game=dove_menuitem("_Game"),*menu=dove_contextmenu();gtk_menu_item_set_submenu(GTK_MENU_ITEM(game),menu);gtk_menu_shell_append(GTK_MENU_SHELL(bar),game);menu_item(menu,"_New\tF2",G_CALLBACK(reset_click));GSList *group=NULL;const char *levels[]={"_Beginner","_Intermediate","_Expert"};for(int i=0;i<3;i++){GtkWidget *item=gtk_radio_menu_item_new_with_mnemonic(group,levels[i]);group=gtk_radio_menu_item_get_group(GTK_RADIO_MENU_ITEM(item));gtk_menu_shell_append(GTK_MENU_SHELL(menu),item);g_signal_connect(item,"toggled",G_CALLBACK(difficulty),GINT_TO_POINTER(i));}GtkWidget *check=gtk_check_menu_item_new_with_mnemonic("_Marks (?)");gtk_check_menu_item_set_active(GTK_CHECK_MENU_ITEM(check),TRUE);gtk_menu_shell_append(GTK_MENU_SHELL(menu),check);g_signal_connect(check,"toggled",G_CALLBACK(mark_toggle),NULL);menu_item(menu,"_Best times",G_CALLBACK(best));menu_item(menu,"E_xit",G_CALLBACK(exit_click));GtkWidget *help=dove_menuitem("_Help"),*hm=dove_contextmenu();gtk_menu_item_set_submenu(GTK_MENU_ITEM(help),hm);gtk_menu_shell_append(GTK_MENU_SHELL(bar),help);menu_item(hm,"_About Minesweeper",G_CALLBACK(about));
 GtkWidget *header=gtk_hbox_new(FALSE,10),*left=counter(),*right=counter();remaining=g_object_get_data(G_OBJECT(left),"label");clock_label=g_object_get_data(G_OBJECT(right),"label");gtk_box_pack_start(GTK_BOX(header),left,FALSE,FALSE,0);GtkWidget *reset=gtk_button_new();gtk_widget_set_can_focus(reset,FALSE);face=gtk_drawing_area_new();gtk_widget_set_size_request(face,24,24);gtk_container_add(GTK_CONTAINER(reset),face);g_signal_connect(face,"expose-event",G_CALLBACK(draw_face),NULL);g_signal_connect(reset,"clicked",G_CALLBACK(reset_click),NULL);gtk_box_pack_start(GTK_BOX(header),reset,TRUE,FALSE,0);gtk_box_pack_end(GTK_BOX(header),right,FALSE,FALSE,0);GtkWidget *header_frame=gtk_frame_new(NULL);gtk_frame_set_shadow_type(GTK_FRAME(header_frame),GTK_SHADOW_IN);gtk_container_set_border_width(GTK_CONTAINER(header),5);gtk_container_add(GTK_CONTAINER(header_frame),header);dove_pack(box,header_frame,FALSE);
 board=gtk_drawing_area_new();gtk_widget_set_can_focus(board,TRUE);gtk_widget_add_events(board,GDK_BUTTON_PRESS_MASK|GDK_KEY_PRESS_MASK);g_signal_connect(board,"expose-event",G_CALLBACK(draw_board),NULL);g_signal_connect(board,"button-press-event",G_CALLBACK(press),NULL);g_signal_connect(board,"key-press-event",G_CALLBACK(key),NULL);g_signal_connect(window,"key-press-event",G_CALLBACK(key),NULL);GtkWidget *frame=gtk_frame_new(NULL);gtk_frame_set_shadow_type(GTK_FRAME(frame),GTK_SHADOW_IN);gtk_container_add(GTK_CONTAINER(frame),board);dove_pack(box,frame,FALSE);new_game();gtk_widget_show_all(window);gtk_widget_grab_focus(board);gtk_main();dove_preferences_free(prefs);g_rand_free(randomness);return 0;}
